def bell_number(n):
    if n <= 0:
        return 1
    row = [1]
    for i in range(1, n + 1):
        new_row = [1]
        for j in range(1, i + 1):
            new_row.append(row[j - 1] + row[j])
        row = new_row
    return row[-1]
```

