def bell_number(n):
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        new_dp = [0] * (n + 1)
        for j in range(i + 1):
            new_dp[j] = dp[j - 1] + dp[j] if j > 0 else dp[j]
        dp = new_dp
    return dp[n]
```

