def next_smallest_palindrome(num):
    num_str = str(num)
    length = len(num_str)

    # Try to form the next palindrome by mirroring the first half
    half_len = length // 2
    first_half = num_str[:half_len]

    # Try increasing the middle digit(s) if needed
    for i in range(1, 10):
        if i == 0:
            continue
        # Construct candidate by incrementing the middle part
        if length % 2 == 0:
            mid = first_half[-1]
        else:
            mid = num_str[half_len]

        # Try incrementing the middle digit
        if i > int(mid):
            continue

        # Try incrementing the first half
        try:
            incremented_half = str(int(first_half) + 1)
            if len(incremented_half) > len(first_half):
                # Overflow case: e.g., 99 -> 100, handle separately
                pass
            else:
                if length % 2 == 0:
                    candidate = incremented_half + incremented_half[::-1]
                else:
                    candidate = incremented_half + num_str[half_len] + incremented_half[::-1]
                return int(candidate)
        except ValueError:
            continue

        # Try keeping the middle digit and mirroring
        if length % 2 == 0:
            candidate = first_half + first_half[::-1]
        else:
            candidate = first_half + num_str[half_len] + first_half[::-1]
        return int(candidate)

    # Overflow case
    if length == 2:
        return 101
    return 100...001
```

