def find_length(string): 
    n = len(string)
    max_sum = 0
    current_sum = 0
    for i in range(n):
        if string[i] == '0':
            current_sum += 1
        else:
            current_sum -= 1

        if current_sum < 0:
            current_sum = 0
        max_sum = max(max_sum, current_sum)

    return max_sum if max_sum else 0
```

