def is_majority(arr, n, x):
    # Find first occurrence of x
    left, right = 0, n - 1
    first = -1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            if mid == 0 or arr[mid - 1] != x:
                first = mid
                break
            right = mid - 1
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1

    if first == -1:
        return False

    # Check if x appears more than n/2 times
    # In a sorted array, if the element at index (first + n//2) is x, then it's a majority
    if first + n // 2 < n and arr[first + n // 2] == x:
        return True
    return False
