def get_total_number_of_sequences(m, n):
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        dp[i][1] = 1
    for length in range(2, n + 1):
        for end in range(1, m + 1):
            start = end // 2
            if start < 1:
                continue
            dp[end][length] = sum(dp[s][length - 1] for s in range(start, end + 1))
