    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                if lis[i] < lis[j] + arr[i]:
                    lis[i] = lis[j] + arr[i]

    # LDS from right to left starting at i (i.e., decreasing towards the right)
    lds = arr[:]
    for i in range(n - 1, -1, -1):
        for j in range(n - 1, i, -1):
            if arr[i] > arr[j]:
                if lds[i] < lds[j] + arr[i]:
                    lds[i] = lds[j] + arr[i]

    max_total = 0
    for i in range(n):
        total = lis[i] + lds[i] - arr[i]
        if total > max_total:
            max_total = total

    return max_total
