import math

def find_solution(a, b, n):
    if a == 0 and b == 0:
        return None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    g = math.gcd(a, b)
    if n % g != 0:
        return None

    # Extended Euclidean Algorithm to find u, v such that a*u + b*v = g
    def extended_gcd(a, b):
        if b == 0:
            return (1, 0)
        u, v = extended_gcd(b, a % b)
        return (v, u - (a // b) * v)

    u, v = extended_gcd(a, b)
    # Now a*u + b*v = g, scale to get n
    u *= n // g
    v *= n // g

    # General solution: x = u + (b/g)*t, y = v - (a/g)*t
    # We can choose t to make x non-negative and minimal
    step_x = b // g
    step_y = a // g

    # Adjust u to be in [0, step_x)
    t = - (u % step_x) // step_x
    x = u + step_x * t
    y = v - step_y * t

    return (x, y)
```

