def get_max_sum(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1

    memo = {0: 0, 1: 1}

    def dp(x: int) -> int:
        if x in memo:
            return memo[x]
        # Compute recursively with memoization
        val1 = dp(x // 2) + dp(x // 3) + dp(x // 4) + dp(x // 5)
        result = max(val1, x)
        memo[x] = result
        return result

    return dp(n)
```

