def get_max_sum(n: int) -> int:
    if n <= 0:
        return 0

    # Memoization table
    memo = {}

    def dp(x):
        if x in memo:
            return memo[x]
        if x == 0 or x == 1:
            memo[x] = x
            return x

        # Option 1: take x itself
        option1 = x
        # Option 2: use the recursive formula
        option2 = dp(x // 2) + dp(x // 3) + dp(x // 4) + dp(x // 5)

        res = max(option1, option2)
        memo[x] = res
        return res

    return dp(n)
```

