def next_smallest_palindrome(n: int) -> int:
    """Return the smallest palindrome strictly greater than n."""
    # If n is already a palindrome, we need the next one.
    # For single-digit numbers, the next palindrome is n+1.
    if n < 10:
        return n + 1

    # Convert to list of digits for manipulation
    s = str(n)
    length = len(s)
    half = length // 2
    left = s[:half]
    right = s[half:] if length % 2 == 0 else s[half+1:]

    # Build the palindrome from the left half
    def make_pal(left_part: str) -> int:
        if length % 2 == 1:
            return int(left_part + left_part[-1::-1])
        else:
            return int(left_part + left_part[::-1])

    # Try current left half
    candidate = make_pal(left)
    if candidate > n:
        return candidate

    # Try incrementing the left half
    try:
        left_inc = str(int(left) + 1)
    except OverflowError:
        # Should not happen for normal int sizes in Python
        return None
    candidate = make_pal(left_inc)
    if candidate > n:
        return candidate

    # Edge case: rolling over (e.g., 99 -> 101)
    if left_inc == '1' and len(left_inc) > len(left):
        # e.g., 99 -> 100 -> 101
        return int('1' + '0' * (length - 1) + '1')

    return candidate
```

