    """
    Count how many characters appear at the same index in the string as in the alphabet.
    The alphabet is 0-indexed: 'a' or 'A' -> 0, 'b' or 'B' -> 1, ..., 'z' or 'Z' -> 25.
    """
    count = 0
    for i, ch in enumerate(s):
        if 'a' <= ch <= 'z':
            expected = ord(ch) - ord('a')
        else:
            expected = ord(ch) - ord('A')
        if i == expected:
            count += 1
    return count
```

