def is_majority(arr, n, elem):
    if n == 0:
        return False
    left = 0
    right = n - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == elem:
            if mid == 0 or arr[mid - 1] != elem:
                first = mid
            elif mid == n - 1 or arr[mid + 1] != elem:
                last = mid
            else:
                left = mid + 1
            continue
        elif arr[mid] < elem:
            left = mid + 1
        else:
            right = mid - 1
    if first is None or last is None:
        return False
    return (last - first + 1) > n // 2
```

