def search(arr):
    n = len(arr)
    if n == 0: return 0
    if arr[0] != arr[1]: return 1
    low, high = 0, n - 1
    while low < high:
        mid = (low + high) // 2
        if mid % 2 == 1:
            mid -= 1
        if arr[mid] == arr[mid+1]:
            low = mid + 2
        else:
            high = mid
    return arr[low]
