def count_no_of_ways(n, k):
    if n == 0:
        return 0
    if n == 1:
        return k
    if n == 2:
        return k * k
    dp_prev2 = k
    dp_prev1 = k * k
    for _ in range(3, n + 1):
        dp_curr = (k - 1) * (dp_prev1 + dp_prev2)
        dp_prev2, dp_prev1 = dp_prev1, dp_curr
    return dp_prev1
```

